type Client=Awaited<ReturnType<typeof createServiceClient>>
const table=(client:Client,name:string)=>client.from(`${REVENUE_VIEW_PREFIX}${name}`)
const arr=(value:unknown):string[]=>Array.isArray(value)?value.map(String):[]
const num=(value:unknown,fallback=0)=>{const parsed=Number(value);return Number.isFinite(parsed)?parsed:fallback}
const iso=(value:unknown)=>typeof value==='string'&&value?value:null
const obj=(value:unknown):Record<string,any>=>value&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,any>:{}
const mapAddress=(value:unknown):Address=>{const row=obj(value);return{id:String(row.id||''),label:String(row.label||'Adresse'),line1:String(row.line1||''),line2:String(row.line2||''),city:String(row.city||''),region:String(row.region||''),postalCode:String(row.postalCode||row.postal_code||''),country:String(row.country||'Maroc'),deliveryZone:String(row.deliveryZone||row.delivery_zone||''),isBilling:Boolean(row.isBilling??row.is_billing),isDelivery:Boolean(row.isDelivery??row.is_delivery)}}
const code=(prefix:string)=>`${prefix}-${new Date().toISOString().replace(/\D/g,'').slice(0,14)}-${randomUUID().slice(0,5).toUpperCase()}`
async function safe<T>(operation:()=>Promise<T>,fallback:T):Promise<T>{try{return await operation()}catch{return fallback}}
async function audit(client:Client,actor:ActorContext,eventType:string,entityType:string,entityId:string,payload:Record<string,unknown>={}){await table(client,'audit_events').insert({tenant_key:REVENUE_TENANT_KEY,event_type:eventType,entity_type:entityType,entity_id:entityId,actor_id:actor.id,actor_name:actor.name,actor_role:actor.role,payload});await table(client,'outbox_events').insert({tenant_key:REVENUE_TENANT_KEY,event_type:eventType,aggregate_type:entityType,aggregate_id:entityId,payload:{...payload,actor},status:'pending'})}
