function mapLearner(row:any):Learner{const profile=obj(row.need_profile);return{id:String(row.id),code:String(row.code||''),householdId:String(row.household_id||''),displayName:String(row.display_name||''),dateOfBirth:iso(row.date_of_birth),ageBand:String(row.age_band||''),preferredLanguages:arr(row.preferred_languages),developmentStage:String(row.development_stage||''),attentionProfile:String(row.attention_profile||''),privacyClass:(['standard','sensitive','restricted'].includes(row.privacy_class)?row.privacy_class:'sensitive') as Learner['privacyClass'],needProfile:{learnerProfileKeys:arr(profile.learnerProfileKeys||row.learner_profile_keys),usageContextKeys:arr(profile.usageContextKeys||row.usage_context_keys),painPointKeys:arr(profile.painPointKeys||row.pain_point_keys),capabilityObjectiveKeys:arr(profile.capabilityObjectiveKeys||row.capability_objective_keys),desiredOutcomeKeys:arr(profile.desiredOutcomeKeys||row.desired_outcome_keys),supportRequirements:arr(profile.supportRequirements||row.support_requirements),preferredFormats:arr(profile.preferredFormats||row.preferred_formats),currentLevel:String(profile.currentLevel||row.current_level||''),targetLevel:String(profile.targetLevel||row.target_level||'')},activeProgrammeIds:arr(row.active_programme_ids),recommendedSellableIds:arr(row.recommended_sellable_ids),recommendedPlanIds:arr(row.recommended_plan_ids),consentStatus:String(row.consent_status||'pending'),createdAt:iso(row.created_at)}}
function mapOpportunity(row:any):Opportunity{return{id:String(row.id),code:String(row.code||''),universe:row.universe==='b2b'?'b2b':'b2c',customerId:String(row.customer_id||''),customerName:String(row.customer_name||''),learnerId:iso(row.learner_id),siteIds:arr(row.site_ids),title:String(row.title||''),stage:row.stage,probability:num(row.probability),valueDh:num(row.value_dh),weightedValueDh:num(row.weighted_value_dh,num(row.value_dh)*num(row.probability)/100),expectedCloseDate:iso(row.expected_close_date),owner:String(row.owner||''),nextAction:String(row.next_action||''),nextActionDueAt:iso(row.next_action_due_at),recommendationId:iso(row.recommendation_id),sellableIds:arr(row.sellable_ids),readyPlanIds:arr(row.ready_plan_ids),releaseIds:arr(row.release_ids),stakeholderIds:arr(row.stakeholder_ids),risks:arr(row.risks),competitor:String(row.competitor||''),lossReason:String(row.loss_reason||''),renewalPotentialDh:num(row.renewal_potential_dh),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at)}}
function lineFromRow(row:any):CommercialLine{const source=obj(row.source_snapshot);return{id:String(row.id),source:{sourceType:source.sourceType||row.source_type||'custom_authorised',sourceId:String(source.sourceId||row.source_id||''),sourceVersion:num(source.sourceVersion||row.source_version,1),code:String(source.code||row.source_code||''),label:String(source.label||row.description||''),releaseIds:arr(source.releaseIds||row.release_ids)},description:String(row.description||''),quantity:num(row.quantity),unit:String(row.unit||'unit'),unitPriceDh:num(row.unit_price_dh),unitCostDh:num(row.unit_cost_dh),discountPercent:num(row.discount_percent),taxPercent:num(row.tax_percent),deliveryRequired:Boolean(row.delivery_required),digitalEntitlementRequired:Boolean(row.digital_entitlement_required),netUnitPriceDh:num(row.net_unit_price_dh),subtotalBeforeTaxDh:num(row.subtotal_before_tax_dh),discountDh:num(row.discount_dh),taxDh:num(row.tax_dh),totalDh:num(row.total_dh),costTotalDh:num(row.cost_total_dh),grossMarginDh:num(row.gross_margin_dh),grossMarginPercent:num(row.gross_margin_percent),deliveredQuantity:num(row.delivered_quantity),invoicedQuantity:num(row.invoiced_quantity),creditedQuantity:num(row.credited_quantity)}}
