export async function loadRevenueOverview():Promise<RevenueOverview>{
  return safe<RevenueOverview>(async()=>{
    const client=await createServiceClient()
    const [hh,lr,ac,st,opp,quotes,orders,invoices,payments,balances,approvals]=await Promise.all([
      table(client,'b2c_households').select('id',{count:'exact',head:true}),
      table(client,'b2c_learners').select('id',{count:'exact',head:true}),
      table(client,'b2b_accounts').select('id',{count:'exact',head:true}),
      table(client,'b2b_account_sites').select('id',{count:'exact',head:true}),
      table(client,'opportunities').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'quotations').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'sales_orders').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'invoices').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'payments').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'customer_balances').select('*').eq('tenant_key',REVENUE_TENANT_KEY),
      table(client,'commercial_approvals').select('id,status').eq('status','pending'),
    ])
    const opportunityRows:any[]=(opp.data||[]) as any[]
    const quoteRows:any[]=(quotes.data||[]) as any[]
    const orderRows:any[]=(orders.data||[]) as any[]
    const invoiceRows:any[]=(invoices.data||[]) as any[]
    const paymentRows:any[]=(payments.data||[]) as any[]
    const balanceRows:any[]=(balances.data||[]) as any[]
    const opportunities:Opportunity[]=opportunityRows.map((row:any)=>mapOpportunity(row))
    const balancesMapped:CustomerBalance[]=balanceRows.map((row:any)=>mapBalance(row))
    const pipeline=(universe:'b2c'|'b2b'):PipelineSummary[]=>{
      const grouped:Record<string,PipelineSummary>={}
      for(const item of opportunities.filter((candidate:Opportunity)=>candidate.universe===universe)){
        const key=item.stage
        grouped[key]??={stage:item.stage,label:item.stage.replaceAll('_',' '),count:0,valueDh:0,weightedValueDh:0}
        grouped[key].count+=1
        grouped[key].valueDh=money(grouped[key].valueDh+item.valueDh)
        grouped[key].weightedValueDh=money(grouped[key].weightedValueDh+item.weightedValueDh)
      }
      return Object.values(grouped)
    }
    return {
      sourceMode:'database',
      generatedAt:new Date().toISOString(),
      b2cHouseholds:hh.count||0,
      b2cLearners:lr.count||0,
      b2bAccounts:ac.count||0,
      b2bSites:st.count||0,
      openOpportunities:opportunities.filter((item:Opportunity)=>!['won','lost'].includes(item.stage)).length,
      pipelineValueDh:money(opportunities.reduce((sum:number,item:Opportunity)=>sum+item.valueDh,0)),
      weightedForecastDh:money(opportunities.reduce((sum:number,item:Opportunity)=>sum+item.weightedValueDh,0)),
      quotationsAwaitingDecision:quoteRows.filter((row:any)=>row.customer_decision==='pending').length,
      confirmedOrders:orderRows.filter((row:any)=>row.status!=='cancelled').length,
      deliveredUninvoicedDh:money(orderRows.reduce((sum:number,row:any)=>sum+num(row.remaining_invoice_value_dh),0)),
      invoiceValueDh:money(invoiceRows.reduce((sum:number,row:any)=>sum+num(row.total_dh),0)),
      collectedDh:money(paymentRows.filter((row:any)=>row.status!=='reversed').reduce((sum:number,row:any)=>sum+num(row.amount_dh),0)),
      outstandingDh:money(balancesMapped.reduce((sum:number,item:CustomerBalance)=>sum+item.outstandingDh,0)),
      overdueDh:money(balancesMapped.reduce((sum:number,item:CustomerBalance)=>sum+item.overdueDh,0)),
      approvalQueue:approvals.data?.length||0,
      b2cPipeline:pipeline('b2c'),
      b2bPipeline:pipeline('b2b'),
      recentDocuments:[
        ...quoteRows.slice(0,5).map((row:any)=>({type:'quotation' as const,id:String(row.id),number:String(row.number||''),customer:String(row.customer_name||''),status:String(row.status||''),totalDh:num(row.total_dh),date:String(row.issue_date||row.created_at||'')})),
        ...invoiceRows.slice(0,5).map((row:any)=>({type:'invoice' as const,id:String(row.id),number:String(row.number||''),customer:String(row.customer_name||''),status:String(row.status||''),totalDh:num(row.total_dh),date:String(row.issue_date||row.created_at||'')})),
      ].slice(0,8),
      interventionQueue:balancesMapped.filter((item:CustomerBalance)=>item.overdueDh>0).map((item:CustomerBalance)=>({severity:'high' as const,title:`Encours ${item.customerName}`,description:`${item.overdueDh.toFixed(2)} Dh en retard.`,href:'/flashcards-os/revenue/payments'})),
      customerBalances:balancesMapped,
    }
  },controlledRevenueOverview)
}

export async function listHouseholds():Promise<Household[]>{return safe(async()=>{const client=await createServiceClient();const [households,guardians,learners,addresses]=await Promise.all([table(client,'b2c_households').select('*').eq('tenant_key',REVENUE_TENANT_KEY).order('created_at',{ascending:false}),table(client,'b2c_guardians').select('*').eq('tenant_key',REVENUE_TENANT_KEY),table(client,'b2c_learners').select('*').eq('tenant_key',REVENUE_TENANT_KEY),table(client,'b2c_household_addresses').select('*').eq('tenant_key',REVENUE_TENANT_KEY)]);return(households.data||[]).map((row:any)=>mapHousehold(row,guardians.data||[],learners.data||[],addresses.data||[]))},controlledHouseholds)}
export async function getHousehold(id:string){return(await listHouseholds()).find(item=>item.id===id)||controlledHouseholds[0]||null}
export async function getLearner(id:string){const households=await listHouseholds();return households.flatMap(item=>item.learners).find(item=>item.id===id)||controlledHouseholds.flatMap(item=>item.learners).find(item=>item.id===id)||null}
