async function nextNumber(client:Client,type:string){const result=await client.rpc('flashcards_os_next_revenue_document_number',{p_tenant_key:REVENUE_TENANT_KEY,p_document_type:type});if(!result.error&&result.data)return String(result.data);return code(DOCUMENT_NUMBER_PREFIX[type]||type.toUpperCase())}
async function writeLines(client:Client,tableName:string,parentField:string,parentId:string,lines:CommercialLine[]){if(!lines.length)return;await table(client,tableName).insert(lines.map(line=>({tenant_key:REVENUE_TENANT_KEY,[parentField]:parentId,id:line.id,source_snapshot:line.source,description:line.description,quantity:line.quantity,unit:line.unit,unit_price_dh:line.unitPriceDh,unit_cost_dh:line.unitCostDh,discount_percent:line.discountPercent,tax_percent:line.taxPercent,delivery_required:line.deliveryRequired,digital_entitlement_required:line.digitalEntitlementRequired,net_unit_price_dh:line.netUnitPriceDh,subtotal_before_tax_dh:line.subtotalBeforeTaxDh,discount_dh:line.discountDh,tax_dh:line.taxDh,total_dh:line.totalDh,cost_total_dh:line.costTotalDh,gross_margin_dh:line.grossMarginDh,gross_margin_percent:line.grossMarginPercent,delivered_quantity:line.deliveredQuantity,invoiced_quantity:line.invoicedQuantity,credited_quantity:line.creditedQuantity})))}

export async function createHousehold(input:CreateHouseholdInput,actor:ActorContext){const client=await createServiceClient();const existing=await table(client,'b2c_households').select('id,email,phone').eq('tenant_key',REVENUE_TENANT_KEY);const duplicateRows=(existing.data||[]).filter((row:any)=>(input.email&&String(row.email).toLowerCase()===input.email.toLowerCase())||(input.phone&&String(row.phone).replace(/\D/g,'')===input.phone.replace(/\D/g,'')));const id=randomUUID();const household={id,tenant_key:REVENUE_TENANT_KEY,code:code('B2C-HH'),display_name:input.displayName,primary_guardian_name:input.primaryGuardianName,email:input.email,phone:input.phone,city:input.city,preferred_language:input.preferredLanguage||'Français',preferred_channel:'Email',acquisition_source:input.acquisitionSource||'Direct',consent_status:'pending',marketing_preference:'none',customer_tier:'Standard',relationship_owner:actor.name,relationship_health:50};const {error}=await table(client,'b2c_households').insert(household);if(error)throw error;await table(client,'b2c_guardians').insert({tenant_key:REVENUE_TENANT_KEY,household_id:id,full_name:input.primaryGuardianName,relationship:'Guardian',email:input.email,phone:input.phone,preferred_channel:'Email',primary_decision_maker:true,billing_contact:true,delivery_contact:true,consent_status:'pending',notes:''});for(const duplicate of duplicateRows){await table(client,'crm_duplicate_candidates').insert({tenant_key:REVENUE_TENANT_KEY,universe:'b2c',left_entity_id:String(duplicate.id),right_entity_id:id,match_score:1,reasons:['email_or_phone_match'],status:'open'})}await audit(client,actor,'b2c.household.created','b2c_household',id,{code:household.code,duplicateCandidates:duplicateRows.length});revalidatePath('/flashcards-os/revenue/b2c/households');return{id,code:household.code}}
export async function createLearner(input:CreateLearnerInput,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:REVENUE_TENANT_KEY,household_id:input.householdId,code:code('LRN'),display_name:input.displayName,date_of_birth:input.dateOfBirth||null,age_band:input.ageBand,preferred_languages:input.preferredLanguages,development_stage:input.developmentStage,attention_profile:'',privacy_class:'sensitive',need_profile:{learnerProfileKeys:[],usageContextKeys:[],painPointKeys:[],capabilityObjectiveKeys:[],desiredOutcomeKeys:[],supportRequirements:[],preferredFormats:[],currentLevel:'',targetLevel:''},consent_status:input.consentStatus};const {error}=await table(client,'b2c_learners').insert(row);if(error)throw error;await audit(client,actor,'b2c.learner.created','b2c_learner',id,{householdId:input.householdId});revalidatePath(`/flashcards-os/revenue/b2c/households/${input.householdId}`);return{id,code:row.code}}
export async function createB2BAccount(input:CreateB2BAccountInput,actor:ActorContext){const client=await createServiceClient();const existing=await table(client,'b2b_accounts').select('id,legal_name,ice').eq('tenant_key',REVENUE_TENANT_KEY);const duplicateRows=(existing.data||[]).filter((row:any)=>String(row.legal_name||'').trim().toLowerCase()===input.legalName.trim().toLowerCase()||(input.ice&&String(row.ice||'').trim()===input.ice.trim()));const id=randomUUID();const row={id,tenant_key:REVENUE_TENANT_KEY,code:code('B2B-ACC'),legal_name:input.legalName,commercial_name:input.commercialName||input.legalName,legal_form:input.legalForm||'',ice:input.ice||'',tax_identifier:'',sector:input.sector,segment:input.segment,website:input.website||'',main_phone:input.mainPhone,headquarters_city:input.headquartersCity,account_owner:actor.name,account_status:'active',strategic_tier:'C',credit_conditions:'Comptant',contract_status:'prospect',relationship_health:50};const {error}=await table(client,'b2b_accounts').insert(row);if(error)throw error;for(const duplicate of duplicateRows){await table(client,'crm_duplicate_candidates').insert({tenant_key:REVENUE_TENANT_KEY,universe:'b2b',left_entity_id:String(duplicate.id),right_entity_id:id,match_score:1,reasons:['legal_name_or_ice_match'],status:'open'})}await audit(client,actor,'b2b.account.created','b2b_account',id,{code:row.code,duplicateCandidates:duplicateRows.length});revalidatePath('/flashcards-os/revenue/b2b/accounts');return{id,code:row.code}}
export async function createOpportunity(input:CreateOpportunityInput,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const probability=input.universe==='b2c'?20:10;const row={id,tenant_key:REVENUE_TENANT_KEY,code:code(input.universe==='b2c'?'OPP-B2C':'OPP-B2B'),universe:input.universe,customer_id:input.customerId,customer_name:input.customerName,learner_id:input.learnerId||null,site_ids:[],title:input.title,stage:input.universe==='b2c'?'new_enquiry':'target_account',probability,value_dh:money(input.valueDh),weighted_value_dh:money(input.valueDh*probability/100),expected_close_date:input.expectedCloseDate||null,owner:input.owner,next_action:'Qualifier la demande',next_action_due_at:null,recommendation_id:null,sellable_ids:input.sellableIds||[],ready_plan_ids:input.readyPlanIds||[],release_ids:input.releaseIds||[],stakeholder_ids:[],risks:[],competitor:'',loss_reason:'',renewal_potential_dh:0};const {error}=await table(client,'opportunities').insert(row);if(error)throw error;await audit(client,actor,`${input.universe}.opportunity.created`,'opportunity',id,{code:row.code});revalidatePath(`/flashcards-os/revenue/${input.universe}/opportunities`);return{id,code:row.code}}
export async function changeOpportunityStage(id:string,stage:string,probability:unknown,actor:ActorContext){const client=await createServiceClient();const p=clampProbability(probability);const existing=await table(client,'opportunities').select('value_dh,universe').eq('id',id).single();if(existing.error)throw existing.error;const {error}=await table(client,'opportunities').update({stage,probability:p,weighted_value_dh:money(num(existing.data?.value_dh)*p/100),updated_at:new Date().toISOString()}).eq('id',id);if(error)throw error;await table(client,'opportunity_stage_events').insert({tenant_key:REVENUE_TENANT_KEY,opportunity_id:id,from_stage:null,to_stage:stage,probability:p,changed_by:actor.name});await audit(client,actor,`${existing.data?.universe||'crm'}.opportunity.stage_changed`,'opportunity',id,{stage,probability:p});revalidatePath(`/flashcards-os/revenue/${existing.data?.universe||'b2c'}/opportunities/${id}`);return{ok:true}}

export async function createQuotation(input:CreateQuotationInput,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'quotation');const {lines,calculation}=calculateCommercialLines(input.lines);const approvalReasons=requiresApproval(lines,calculation.totalDh);const status=approvalReasons.length?'approval_required':'draft';const row={id,tenant_key:REVENUE_TENANT_KEY,number,version_no:1,status,universe:input.universe,customer_id:input.customerId,customer_name:input.customerName,billing_contact:input.billingContact,delivery_contact:input.deliveryContact,opportunity_id:input.opportunityId||null,currency:'Dh',price_book_id:input.priceBookId||null,tax_profile_id:input.taxProfileId||null,issue_date:null,expiry_date:input.expiryDate,payment_terms:input.paymentTerms,delivery_assumptions:input.deliveryAssumptions,commercial_owner:actor.name,customer_decision:'pending',calculation_snapshot:calculation,subtotal_dh:calculation.subtotalDh,discount_dh:calculation.discountDh,tax_dh:calculation.taxDh,total_dh:calculation.totalDh,cost_dh:calculation.costDh,gross_margin_dh:calculation.grossMarginDh,gross_margin_percent:calculation.grossMarginPercent,paid_dh:0,outstanding_dh:calculation.totalDh};const {error}=await table(client,'quotations').insert(row);if(error)throw error;await writeLines(client,'quotation_items','quotation_id',id,lines);for(const reason of approvalReasons)await table(client,'commercial_approvals').insert({tenant_key:REVENUE_TENANT_KEY,document_type:'quotation',document_id:id,rule_key:reason,reason,threshold:0,requested_by:actor.name,assigned_role:'commercial_director',status:'pending'});await audit(client,actor,'quotation.created','quotation',id,{number,totalDh:calculation.totalDh,status});revalidatePath('/flashcards-os/revenue/devis');return{id,number,status}}
export async function recalculateQuotation(id:string,actor:ActorContext){const quote=await getQuotation(id);if(!quote)throw new Error('Quotation not found.');if(!['draft','approval_required','approved'].includes(quote.status))throw new Error('Issued quotations cannot be recalculated destructively.');const result=calculateCommercialLines(quote.lines);const client=await createServiceClient();await table(client,'quotations').update({calculation_snapshot:result.calculation,subtotal_dh:result.calculation.subtotalDh,discount_dh:result.calculation.discountDh,tax_dh:result.calculation.taxDh,total_dh:result.calculation.totalDh,cost_dh:result.calculation.costDh,gross_margin_dh:result.calculation.grossMarginDh,gross_margin_percent:result.calculation.grossMarginPercent,outstanding_dh:result.calculation.totalDh,updated_at:new Date().toISOString()}).eq('id',id);await audit(client,actor,'quotation.recalculated','quotation',id,{totalDh:result.calculation.totalDh});revalidatePath(`/flashcards-os/revenue/devis/${id}`);return result.calculation}
export async function approveDocument(documentType:CommercialDocumentType,id:string,approved:boolean,note:string,actor:ActorContext){const client=await createServiceClient();const target=documentType==='quotation'?'quotations':documentType==='invoice'?'invoices':documentType==='credit_note'?'credit_notes':documentType==='delivery_note'?'delivery_notes':'sales_orders';const status=approved?'approved':'draft';const {error}=await table(client,target).update({status,updated_at:new Date().toISOString()}).eq('id',id);if(error)throw error;await table(client,'commercial_approvals').update({status:approved?'approved':'rejected',decided_by:actor.name,decided_at:new Date().toISOString(),decision_note:note}).eq('document_id',id).eq('status','pending');await audit(client,actor,`${documentType}.${approved?'approved':'rejected'}`,documentType,id,{note});revalidatePath('/flashcards-os/revenue/approvals');return{ok:true}}
export async function issueQuotation(id:string,actor:ActorContext){const client=await createServiceClient();const quote=await getQuotation(id);if(!quote)throw new Error('Quotation not found.');if(quote.status==='approval_required')throw new Error('Quotation approval is required before issue.');if(!['draft','approved'].includes(quote.status))throw new Error('Quotation is not eligible for issue.');const now=new Date().toISOString();const {error}=await table(client,'quotations').update({status:'issued',issue_date:now.slice(0,10),issued_at:now,issued_template_version:DEFAULT_DOCUMENT_TEMPLATE_VERSION,updated_at:now}).eq('id',id);if(error)throw error;await audit(client,actor,'quotation.issued','quotation',id,{number:quote.number});revalidatePath(`/flashcards-os/revenue/devis/${id}`);return{ok:true}}
export async function recordQuotationDecision(id:string,decision:'accepted'|'rejected',actor:ActorContext){const client=await createServiceClient();const quote=await getQuotation(id);if(!quote)throw new Error('Quotation not found.');const now=new Date().toISOString();await table(client,'quotations').update({status:decision==='accepted'?'accepted':'rejected',customer_decision:decision,customer_decision_at:now,updated_at:now}).eq('id',id);await audit(client,actor,`quotation.${decision}`,'quotation',id,{number:quote.number});if(decision==='accepted')return createSalesOrderFromQuotation(quote,actor);revalidatePath(`/flashcards-os/revenue/devis/${id}`);return{ok:true}}
async function createSalesOrderFromQuotation(quote:Quotation,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'sales_order');const now=new Date().toISOString();const row={id,tenant_key:REVENUE_TENANT_KEY,number,status:'confirmed',quotation_id:quote.id,quotation_number:quote.number,universe:quote.universe,customer_id:quote.customerId,customer_name:quote.customerName,confirmed_at:now,calculation_snapshot:quote.calculation,subtotal_dh:quote.calculation.subtotalDh,discount_dh:quote.calculation.discountDh,tax_dh:quote.calculation.taxDh,total_dh:quote.calculation.totalDh,cost_dh:quote.calculation.costDh,gross_margin_dh:quote.calculation.grossMarginDh,gross_margin_percent:quote.calculation.grossMarginPercent,delivered_value_dh:0,invoiced_value_dh:0,remaining_delivery_value_dh:quote.calculation.totalDh,remaining_invoice_value_dh:quote.calculation.totalDh};const {error}=await table(client,'sales_orders').insert(row);if(error)throw error;await writeLines(client,'sales_order_items','sales_order_id',id,quote.lines.map(line=>({...line,deliveredQuantity:0,invoicedQuantity:0,creditedQuantity:0})));await audit(client,actor,'sales_order.created','sales_order',id,{number,quotationId:quote.id});revalidatePath('/flashcards-os/revenue/orders');return{id,number}}

export async function createDelivery(input:CreateDeliveryInput,actor:ActorContext){const order=await getOrder(input.orderId);if(!order)throw new Error('Sales order not found.');const selected=validateDeliveryAllocation(order,input.lines);const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'delivery_note');const selectedLines=selected.map(({line,quantity})=>{const ratio=quantity/line.quantity;return{...line,quantity,totalDh:money(line.totalDh*ratio),subtotalBeforeTaxDh:money(line.subtotalBeforeTaxDh*ratio),discountDh:money(line.discountDh*ratio),taxDh:money(line.taxDh*ratio),costTotalDh:money(line.costTotalDh*ratio),grossMarginDh:money(line.grossMarginDh*ratio),deliveredQuantity:quantity}});const row={id,tenant_key:REVENUE_TENANT_KEY,number,status:'draft',order_id:order.id,order_number:order.number,universe:order.universe,customer_id:input.customerId,customer_name:input.customerName,site_id:input.siteId||null,delivery_address:input.deliveryAddress,delivery_contact:input.deliveryContact,planned_date:input.plannedDate||null,carrier_or_agent:input.carrierOrAgent,notes:'',invoicing_eligible:false};const {error}=await table(client,'delivery_notes').insert(row);if(error)throw error;await writeLines(client,'delivery_note_items','delivery_note_id',id,selectedLines);await audit(client,actor,'delivery_note.created','delivery_note',id,{number,orderId:order.id});revalidatePath('/flashcards-os/revenue/deliveries');return{id,number}}
export async function issueDelivery(id:string,actor:ActorContext){const delivery=await getDelivery(id);if(!delivery)throw new Error('Delivery note not found.');if(delivery.status!=='draft')throw new Error('Only draft delivery notes may be issued.');const client=await createServiceClient();const now=new Date().toISOString();await table(client,'delivery_notes').update({status:'issued',issued_at:now,issued_template_version:DEFAULT_DOCUMENT_TEMPLATE_VERSION,invoicing_eligible:true,updated_at:now}).eq('id',id);for(const line of delivery.lines){const orderItem=await table(client,'sales_order_items').select('delivered_quantity').eq('sales_order_id',delivery.orderId).eq('id',line.id).single();await table(client,'sales_order_items').update({delivered_quantity:money(num(orderItem.data?.delivered_quantity)+line.quantity)}).eq('sales_order_id',delivery.orderId).eq('id',line.id)}await audit(client,actor,'delivery_note.issued','delivery_note',id,{number:delivery.number});revalidatePath(`/flashcards-os/revenue/deliveries/${id}`);return{ok:true}}
export async function createInvoice(input:CreateInvoiceInput,actor:ActorContext){const order=await getOrder(input.orderId);if(!order)throw new Error('Sales order not found.');const deliveries=await listDeliveries();const selected=validateInvoiceSources(order,deliveries,input.sourceLinks);const selectedLines=selected.map(({orderLine,quantity})=>{const ratio=quantity/orderLine.quantity;return{...orderLine,quantity,totalDh:money(orderLine.totalDh*ratio),subtotalBeforeTaxDh:money(orderLine.subtotalBeforeTaxDh*ratio),discountDh:money(orderLine.discountDh*ratio),taxDh:money(orderLine.taxDh*ratio),costTotalDh:money(orderLine.costTotalDh*ratio),grossMarginDh:money(orderLine.grossMarginDh*ratio),invoicedQuantity:quantity}});const calculation=summariseCommercial(selectedLines);const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'invoice');const row={id,tenant_key:REVENUE_TENANT_KEY,number,status:'draft',payment_status:'unpaid',universe:order.universe,customer_id:input.customerId,customer_name:input.customerName,billing_identity:input.billingIdentity,tax_identity:input.taxIdentity,order_id:order.id,issue_date:null,due_date:input.dueDate,currency:'Dh',payment_terms:input.paymentTerms,calculation_snapshot:calculation,subtotal_dh:calculation.subtotalDh,discount_dh:calculation.discountDh,tax_dh:calculation.taxDh,total_dh:calculation.totalDh,cost_dh:calculation.costDh,gross_margin_dh:calculation.grossMarginDh,gross_margin_percent:calculation.grossMarginPercent,paid_dh:0,outstanding_dh:calculation.totalDh,dispute_reason:''};const {error}=await table(client,'invoices').insert(row);if(error)throw error;await writeLines(client,'invoice_items','invoice_id',id,selectedLines);await table(client,'invoice_source_links').insert(input.sourceLinks.map(link=>({tenant_key:REVENUE_TENANT_KEY,invoice_id:id,delivery_note_id:link.deliveryNoteId,delivery_note_number:link.deliveryNoteNumber,sales_order_id:link.salesOrderId,line_id:link.lineId,quantity:link.quantity})));await audit(client,actor,'invoice.created','invoice',id,{number,totalDh:calculation.totalDh});revalidatePath('/flashcards-os/revenue/invoices');return{id,number}}
export async function issueInvoice(id:string,actor:ActorContext){const invoice=await getInvoice(id);if(!invoice)throw new Error('Invoice not found.');if(invoice.status==='approval_required')throw new Error('Invoice approval is required.');if(!['draft','approved'].includes(invoice.status))throw new Error('Invoice is not eligible for issue.');const client=await createServiceClient();const now=new Date().toISOString();await table(client,'invoices').update({status:'issued',issue_date:now.slice(0,10),issued_at:now,issued_template_version:DEFAULT_DOCUMENT_TEMPLATE_VERSION,updated_at:now}).eq('id',id);for(const link of invoice.sourceLinks){const item=await table(client,'sales_order_items').select('invoiced_quantity').eq('sales_order_id',invoice.orderId).eq('id',link.lineId).single();await table(client,'sales_order_items').update({invoiced_quantity:money(num(item.data?.invoiced_quantity)+link.quantity)}).eq('sales_order_id',invoice.orderId).eq('id',link.lineId)}await audit(client,actor,'invoice.issued','invoice',id,{number:invoice.number,totalDh:invoice.calculation.totalDh});revalidatePath(`/flashcards-os/revenue/invoices/${id}`);return{ok:true}}
export async function recordPayment(input:RecordPaymentInput,actor:ActorContext){if(input.amountDh<=0)throw new Error('Payment amount must be greater than zero.');const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'payment');const row={id,tenant_key:REVENUE_TENANT_KEY,number,customer_id:input.customerId,customer_name:input.customerName,universe:input.universe,method:input.method,amount_dh:money(input.amountDh),currency:'Dh',transaction_reference:input.transactionReference,value_date:input.valueDate,received_at:new Date().toISOString(),status:'recorded',evidence_urls:input.evidenceUrls||[],unapplied_amount_dh:money(input.amountDh),recorded_by:actor.name};const {error}=await table(client,'payments').insert(row);if(error)throw error;await audit(client,actor,'payment.recorded','payment',id,{number,amountDh:row.amount_dh});revalidatePath('/flashcards-os/revenue/payments');return{id,number}}
export async function allocatePayment(paymentId:string,invoiceId:string,amountDh:number,actor:ActorContext){const payment=await getPayment(paymentId);const invoice=await getInvoice(invoiceId);if(!payment||!invoice)throw new Error('Payment or invoice not found.');const amount=money(amountDh);if(amount<=0||amount>payment.unappliedAmountDh)throw new Error('Allocation exceeds unapplied payment.');if(amount>invoice.calculation.outstandingDh)throw new Error('Allocation exceeds invoice outstanding balance.');const client=await createServiceClient();await table(client,'payment_allocations').insert({tenant_key:REVENUE_TENANT_KEY,payment_id:paymentId,invoice_id:invoiceId,invoice_number:invoice.number,amount_dh:amount,allocated_at:new Date().toISOString()});const remaining=money(payment.unappliedAmountDh-amount);await table(client,'payments').update({unapplied_amount_dh:remaining,status:remaining===0?'fully_allocated':'partially_allocated'}).eq('id',paymentId);const paid=money(invoice.calculation.paidDh+amount);const outstanding=money(Math.max(0,invoice.calculation.totalDh-paid));await table(client,'invoices').update({paid_dh:paid,outstanding_dh:outstanding,payment_status:outstanding===0?'paid':'partially_paid',status:outstanding===0?'paid':invoice.status}).eq('id',invoiceId);await audit(client,actor,'payment.allocated','payment',paymentId,{invoiceId,amountDh:amount});revalidatePath('/flashcards-os/revenue/payments');return{ok:true,unappliedAmountDh:remaining,invoiceOutstandingDh:outstanding}}
export async function runRevenueIntelligence(task:any,context:unknown,actor:ActorContext){const result=await runCommercialIntelligence(task,context);const client=await createServiceClient();await table(client,'commercial_intelligence_runs').insert({tenant_key:REVENUE_TENANT_KEY,task,actor_id:actor.id,actor_name:actor.name,model_requested:result.modelRequested,model_used:result.modelUsed,fallback_used:result.fallbackUsed,prompt_tokens:result.promptTokens,completion_tokens:result.completionTokens,total_tokens:result.totalTokens,cost_usd:result.costUsd,latency_ms:result.latencyMs,result_payload:result});await audit(client,actor,'commercial_intelligence.completed','commercial_intelligence',randomUUID(),{task,modelUsed:result.modelUsed});return result}

export async function loadCommercialDocument(type:CommercialDocumentType,id:string){if(type==='quotation')return getQuotation(id);if(type==='sales_order')return getOrder(id);if(type==='delivery_note')return getDelivery(id);if(type==='invoice')return getInvoice(id);if(type==='credit_note')return (await listCreditNotes()).find(item=>item.id===id)||null;if(type==='payment_receipt')return getPayment(id);return null}

export async function createB2BSite(input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:REVENUE_TENANT_KEY,account_id:String(input.accountId),code:code('SITE'),name:String(input.name||'Site'),site_type:String(input.siteType||'Site'),address:obj(input.address),classroom_count:num(input.classroomCount),learner_capacity:num(input.learnerCapacity),active_learners:num(input.activeLearners),age_distribution:arr(input.ageDistribution),languages:arr(input.languages),delivery_constraints:arr(input.deliveryConstraints),operational_contact:String(input.operationalContact||''),pedagogical_contact:String(input.pedagogicalContact||''),active_deployment_ids:[]};const {error}=await table(client,'b2b_account_sites').insert(row);if(error)throw error;await audit(client,actor,'b2b.site.created','b2b_site',id,{accountId:row.account_id,code:row.code});revalidatePath(`/flashcards-os/revenue/b2b/accounts/${row.account_id}`);return{id,code:row.code}}
export async function createStakeholder(input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:REVENUE_TENANT_KEY,account_id:String(input.accountId),site_id:input.siteId||null,full_name:String(input.fullName||''),title:String(input.title||''),department:String(input.department||''),email:String(input.email||''),phone:String(input.phone||''),role:String(input.role||'influencer'),decision_authority:num(input.decisionAuthority),influence:num(input.influence),interest:num(input.interest),position:String(input.position||'neutral'),relationship_strength:num(input.relationshipStrength),preferred_channel:String(input.preferredChannel||'Email'),required_action:String(input.requiredAction||''),last_engagement_at:null,next_engagement_at:input.nextEngagementAt||null};const {error}=await table(client,'b2b_stakeholders').insert(row);if(error)throw error;await audit(client,actor,'b2b.stakeholder.created','b2b_stakeholder',id,{accountId:row.account_id});revalidatePath(`/flashcards-os/revenue/b2b/accounts/${row.account_id}`);return{id}}
