export async function addCRMActivity(input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:REVENUE_TENANT_KEY,universe:input.universe==='b2b'?'b2b':'b2c',customer_id:String(input.customerId),opportunity_id:input.opportunityId||null,contact_id:input.contactId||null,activity_type:String(input.type||'note'),title:String(input.title||''),outcome:String(input.outcome||''),next_action:String(input.nextAction||''),due_at:input.dueAt||null,occurred_at:input.occurredAt||new Date().toISOString(),owner:actor.name,visibility:String(input.visibility||'team'),evidence_urls:arr(input.evidenceUrls)};const {error}=await table(client,'crm_activities').insert(row);if(error)throw error;await audit(client,actor,'crm.activity.created','crm_activity',id,{customerId:row.customer_id});return{id}}
export async function createCreditNote(input:any,actor:ActorContext){const invoice=await getInvoice(String(input.invoiceId));if(!invoice)throw new Error('Invoice not found.');const requested=Array.isArray(input.lines)?input.lines:[];if(!requested.length)throw new Error('At least one credit line is required.');const creditLines:CommercialLine[]=requested.map((request:any)=>{const original=invoice.lines.find(line=>line.id===String(request.lineId));if(!original)throw new Error('Invoice line not found.');const quantity=money(request.quantity);const eligible=money(original.quantity-original.creditedQuantity);if(quantity<=0||quantity>eligible)throw new Error(`Credit quantity exceeds eligible quantity for ${original.description}.`);const ratio=quantity/original.quantity;return{...original,quantity,totalDh:money(original.totalDh*ratio),subtotalBeforeTaxDh:money(original.subtotalBeforeTaxDh*ratio),discountDh:money(original.discountDh*ratio),taxDh:money(original.taxDh*ratio),costTotalDh:money(original.costTotalDh*ratio),grossMarginDh:money(original.grossMarginDh*ratio),creditedQuantity:quantity}});const calculation=summariseCommercial(creditLines);if(calculation.totalDh>invoice.calculation.totalDh)throw new Error('Credit note exceeds invoiced value.');const client=await createServiceClient();const id=randomUUID();const number=await nextNumber(client,'credit_note');const row={id,tenant_key:REVENUE_TENANT_KEY,number,status:'approval_required',invoice_id:invoice.id,invoice_number:invoice.number,customer_id:invoice.customerId,customer_name:invoice.customerName,reason:String(input.reason||'Commercial correction'),calculation_snapshot:calculation,subtotal_dh:calculation.subtotalDh,discount_dh:calculation.discountDh,tax_dh:calculation.taxDh,total_dh:calculation.totalDh};const {error}=await table(client,'credit_notes').insert(row);if(error)throw error;await writeLines(client,'credit_note_items','credit_note_id',id,creditLines);await table(client,'commercial_approvals').insert({tenant_key:REVENUE_TENANT_KEY,document_type:'credit_note',document_id:id,rule_key:'credit_note_approval',reason:row.reason,threshold:calculation.totalDh,requested_by:actor.name,assigned_role:'finance_controller',status:'pending'});await audit(client,actor,'credit_note.created','credit_note',id,{number,invoiceId:invoice.id,totalDh:calculation.totalDh});revalidatePath('/flashcards-os/revenue/credit-notes');return{id,number}}
export async function listApprovals(){return safe(async()=>{const client=await createServiceClient();const result=await table(client,'commercial_approvals').select('*').eq('tenant_key',REVENUE_TENANT_KEY).order('requested_at',{ascending:false});return(result.data||[]).map((row:any)=>({id:String(row.id),documentType:row.document_type,documentId:String(row.document_id),ruleKey:String(row.rule_key||''),reason:String(row.reason||''),threshold:num(row.threshold),requestedBy:String(row.requested_by||''),requestedAt:String(row.requested_at||''),assignedRole:String(row.assigned_role||''),status:row.status,decidedBy:iso(row.decided_by),decidedAt:iso(row.decided_at),decisionNote:String(row.decision_note||'')}))},[])}
